#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;
using pii = pair<int, int>;

const ll N = 2e5 + 5;

int n, m, idx[N], fa[N], ch[N][0], rt, t[N];
pii q[N];
set<int> st;

void modify(int x, int v)
{
	for (x = max(x, 1); x <= n; x += x & -x)
		t[x] += v;
}

int query(int x)
{
	int res = 0;
	for (; x; x -= x & -x)
		res += t[x];
	return res;
}

void init() {}

void solve()
{
	cin >> m;
	for (int i = 1; i <= m; ++i)
	{
		cin >> q[i].first;
		if (q[i].first == 1)
		{
			cin >> q[i].second;
			idx[++n] = q[i].second;
		}
	}
	sort(idx + 1, idx + n + 1);
	for (int i = 1; i <= m; ++i)
	{
		if (q[i].first == 1)
			q[i].second = lower_bound(idx + 1, idx + n + 1, q[i].second) - idx;
	}
	for (int i = 1, pre, nxt, x, t; i <= m; ++i)
	{
		if (q[i].first == 1)
		{
			x = q[i].second;
			if (!rt)
			{
				rt = x;
				st.insert(x);
				t = query(x);
				modify(x, 1 - t);
				modify(x + 1, t - 1);
				cout << 1 << endl;
				continue;
			}
			auto it = st.upper_bound(x);
			pre = it == st.begin() ? 0 : *prev(it);
			nxt = it == st.end() ? 0 : *it;
			// cerr << pre << ' ' << nxt << ' ' << query(pre) << ' ' << query(nxt) << endl;
			st.insert(x);
			if (query(pre) > query(nxt))
			{
				fa[x] = pre;
				ch[pre][1] = x;
				t = query(pre) + 1 - query(x);
				modify(x, t);
				modify(x + 1, -t);
			}
			else
			{
				fa[x] = nxt;
				ch[nxt][0] = x;
				t = query(nxt) + 1 - query(x);
				modify(x, t);
				modify(x + 1, -t);
			}
			ch[x][0] = ch[x][1] = 0;
			cout << query(x) << endl;
		}
		else if (q[i].first == 2)
		{
			x = *st.begin();
			if (rt == x)
				continue;
			ch[fa[x]][0] = ch[x][1];
			fa[ch[x][1]] = fa[x];
			ch[x][1] = rt;
			fa[rt] = x;
			rt = x;
			modify(fa[x], 1);
			fa[x] = 0;
			t = query(x);
			cout << t << endl;
			modify(x, 1 - t);
			modify(x + 1, t - 1);
		}
		else if (q[i].first == 3)
		{
			x = *st.rbegin();
			if (rt == x)
				continue;
			ch[fa[x]][1] = ch[x][0];
			fa[ch[x][0]] = fa[x];
			ch[x][0] = rt;
			fa[rt] = x;
			rt = x;
			modify(1, 1);
			modify(fa[x] + 1, -1);
			fa[x] = 0;
			t = query(x);
			cout << t << endl;
			modify(x, 1 - t);
			modify(x + 1, t - 1);
		}
		else if (q[i].first == 4)
		{
			x = *st.begin();
			cout << query(x) << endl;
			if (rt == x)
			{
				rt = 0;
				continue;
			}
			ch[fa[x]][0] = ch[x][1];
			fa[ch[x][1]] = fa[x];
			modify(ch[x][1], -1);
			modify(fa[x], 1);
			st.erase(x);
		}
		else if (q[i].first == 5)
		{
			x = *st.rbegin();
			cout << query(x) << endl;
			if (rt == x)
			{
				rt = 0;
				continue;
			}
			ch[fa[x]][1] = ch[x][0];
			fa[ch[x][0]] = fa[x];
			modify(fa[x] + 1, -1);
			modify(ch[x][0] + 1, 1);
		}
		// end:;
		// 	for (int i = 1; i <= n; ++i)
		// 		cerr << fa[i] << " \n"[i == n];
	}
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

